INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-6', 'lumina-atelier-insights-6', 'Lumina Atelier Industry Brief #6: Signature Gloss & Styling', 'تقرير لومينا أتيليه التخصصي #6: تصفيف وعناية بالشعر', 'Key operational benchmarks and best practices from Lumina Atelier in Riffa.', 'أبرز المعايير التشغيلية وأفضل الممارسات من لومينا أتيليه في Riffa.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Curated beauty atelier combining bespoke facial rituals, hair artistry, and an online botanical skincare apothecary. Our Signature Gloss & Styling division helps regional organizations scale predictably with transparent SLAs and bilingual reporting."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"أتيليه تجميل يجمع بين جلسات العناية بالبشرة المخصصة ومتجر إلكتروني لمنتجات العناية النباتية. يساعد قسم تصفيف وعناية بالشعر المؤسسات الإقليمية على النمو بثبات مع وضوح مستويات الخدمة والتقارير."}]}]}'::jsonb, '<p>Curated beauty atelier combining bespoke facial rituals, hair artistry, and an online botanical skincare apothecary.</p><p>Our Signature Gloss & Styling division helps regional organizations scale predictably with transparent SLAs and bilingual reporting.</p>', '<p>أتيليه تجميل يجمع بين جلسات العناية بالبشرة المخصصة ومتجر إلكتروني لمنتجات العناية النباتية.</p><p>يساعد قسم تصفيف وعناية بالشعر المؤسسات الإقليمية على النمو بثبات مع وضوح مستويات الخدمة والتقارير.</p>', 'beauty', '{"beauty","Riffa","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '54 days', false, now() - interval '54 days', now()) ON CONFLICT (id) DO NOTHING;
